// ─── CONFIG ───────────────────────────────────────────────────────────────────

const AMBA_CENTER = [-34.62, -58.65];
const AMBA_ZOOM   = 9;
const AMBA_BOUNDS = L.latLngBounds(
  L.latLng(-35.50, -59.60),
  L.latLng(-33.80, -57.40)
);
const MAX_DISTANCE_KM = 50;

const ROUND_CONFIG = [
  { zone: 'caba',    mult: 1 },
  { zone: 'caba',    mult: 1 },
  { zone: 'cordon1', mult: 2 },
  { zone: 'cordon2', mult: 3 },
  { zone: 'cordon3', mult: 3 },
];

// ─── STATE ────────────────────────────────────────────────────────────────────

let activeRounds  = [];
let totalRounds  = 5;
let gameMode     = 'daily'; // 'daily' | 'practice'
let currentRound = 0;
let totalScore   = 0;
let results      = [];

let map          = null;
let miniMap      = null;
let guessMarker  = null;
let pendingGuess = null;

// ─── HELPERS ─────────────────────────────────────────────────────────────────

function today() {
  const d = new Date();
  return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;
}

function todayDisplay() {
  const d = new Date();
  return `${String(d.getDate()).padStart(2,'0')}/${String(d.getMonth()+1).padStart(2,'0')}/${d.getFullYear()}`;
}

function seededRng(seed) {
  return function() {
    seed |= 0; seed = seed + 0x6D2B79F5 | 0;
    let t = Math.imul(seed ^ seed >>> 15, 1 | seed);
    t = t + Math.imul(t ^ t >>> 7, 61 | t) ^ t;
    return ((t ^ t >>> 14) >>> 0) / 4294967296;
  };
}

function dateSeed(dateStr) {
  let hash = 0;
  for (const c of dateStr) hash = (Math.imul(31, hash) + c.charCodeAt(0)) | 0;
  return Math.abs(hash);
}

function pickDaily(db) {
  const seed  = dateSeed(today());
  const rand  = seededRng(seed);
  const usedIds = new Set();

  return ROUND_CONFIG.map(({ zone, mult }) => {
    const pool = db.zones[zone];
    // Fisher-Yates shuffle virtual: buscar un ítem no usado aún
    let pick, attempts = 0;
    do {
      const idx = Math.floor(rand() * pool.length);
      pick = pool[idx];
      attempts++;
    } while (usedIds.has(pick.id) && attempts < pool.length * 3);
    usedIds.add(pick.id);
    return { ...pick, mult };
  });
}

const PRACTICE_MAX = 20;
const PRACTICE_ROUND_SIZE = 20;

function practiceKey() {
  return `amba-practice-${today()}`;
}

function getPracticeCount() {
  try {
    const raw = localStorage.getItem(practiceKey());
    return raw ? (JSON.parse(raw).count || 0) : 0;
  } catch { return 0; }
}

function addPracticeCount(n) {
  try {
    localStorage.setItem(practiceKey(), JSON.stringify({ count: getPracticeCount() + n }));
  } catch(e) {}
}

function pickPractice(n) {
  const allPool = [].concat(
    INTERSECTIONS_DB.zones.caba,
    INTERSECTIONS_DB.zones.cordon1,
    INTERSECTIONS_DB.zones.cordon2,
    INTERSECTIONS_DB.zones.cordon3
  );
  const usedIds = new Set();
  const picks = [];
  let attempts = 0;
  while (picks.length < n && attempts < n * 20) {
    attempts++;
    const idx = Math.floor(Math.random() * allPool.length);
    const cand = allPool[idx];
    if (usedIds.has(cand.id)) continue;
    usedIds.add(cand.id);
    picks.push({ ...cand, mult: 1 });
  }
  return picks;
}

function haversineKm(lat1, lon1, lat2, lon2) {
  const R    = 6371;
  const dLat = (lat2 - lat1) * Math.PI / 180;
  const dLon = (lon2 - lon1) * Math.PI / 180;
  const a    = Math.sin(dLat/2)**2 +
               Math.cos(lat1 * Math.PI/180) * Math.cos(lat2 * Math.PI/180) *
               Math.sin(dLon/2)**2;
  return R * 2 * Math.asin(Math.sqrt(a));
}

function calcScore(distKm, mult) {
  const raw   = Math.round(Math.max(0, 100 * (1 - distKm / MAX_DISTANCE_KM)));
  return { raw, final: raw * mult };
}

function formatDist(km) {
  if (km < 1) return `${Math.round(km * 1000)} m`;
  return `${km.toFixed(2)} km`;
}

function showScreen(id) {
  document.querySelectorAll('.screen').forEach(s => s.classList.remove('active'));
  document.getElementById(id).classList.add('active');
}

// ─── MAP ──────────────────────────────────────────────────────────────────────

function initMap() {
  if (map) return;  // ya inicializado

  map = L.map('map', {
    center: AMBA_CENTER,
    zoom: AMBA_ZOOM,
    minZoom: 8,
    maxZoom: 17,
    maxBounds: AMBA_BOUNDS,
    maxBoundsViscosity: 0.9,
    zoomControl: true,
  });

  L.tileLayer(
    'https://server.arcgisonline.com/ArcGIS/rest/services/World_Imagery/MapServer/tile/{z}/{y}/{x}',
    { attribution: 'Tiles © Esri', maxZoom: 19 }
  ).addTo(map);

  map.on('click', onMapClick);
}

let showingResult = false;

function showConfirmOverlay() {
  document.getElementById('confirm-overlay').classList.add('visible');
}
function hideConfirmOverlay() {
  document.getElementById('confirm-overlay').classList.remove('visible');
}

function onMapClick(e) {
  if (showingResult) return;
  if (guessMarker) map.removeLayer(guessMarker);
  pendingGuess = e.latlng;
  guessMarker  = L.marker(e.latlng, { icon: makePinIcon('guess') }).addTo(map);
  showConfirmOverlay();
}

function makePinIcon(type) {
  return L.divIcon({
    className: '',
    html: `<div class="${type}-pin"></div>`,
    iconSize:   [20, 20],
    iconAnchor: [10, 20],
  });
}

// ─── ROUND ────────────────────────────────────────────────────────────────────

function buildDots() {
  const container = document.getElementById('guess-dots');
  container.innerHTML = '';
  for (let i = 0; i < totalRounds; i++) {
    const dot = document.createElement('span');
    dot.className = 'dot';
    dot.id = `dot-${i + 1}`;
    container.appendChild(dot);
  }
}

function updateDots() {
  for (let i = 1; i <= totalRounds; i++) {
    const dot = document.getElementById(`dot-${i}`);
    if (!dot) continue;
    dot.classList.remove('done', 'active');
    if (i - 1 < currentRound)      dot.classList.add('done');
    else if (i - 1 === currentRound) dot.classList.add('active');
  }
}

function startRound(idx) {
  currentRound  = idx;
  pendingGuess  = null;
  guessMarker   = null;
  showingResult = false;

  // Ocultar overlays
  document.getElementById('result-bar').classList.add('hidden');
  hideConfirmOverlay();

  // Limpiar marcadores del mapa
  map.eachLayer(layer => {
    if (layer instanceof L.Marker || layer instanceof L.Polyline) map.removeLayer(layer);
  });
  map.setView(AMBA_CENTER, AMBA_ZOOM);

  const round    = activeRounds[idx];
  const multText = round.mult > 1 ? `x${round.mult}` : '';
  document.getElementById('round-label').textContent      = `Ronda ${idx + 1} de ${totalRounds}`;
  document.getElementById('round-multiplier').textContent = multText;
  document.getElementById('clue-text').textContent        =
    `${round.street_label} — ${round.location_label}`;

  if (idx === 0) buildDots();
  updateDots();
  showScreen('screen-game');

  // Forzar redibujado del mapa (necesario al mostrar el div)
  setTimeout(() => map.invalidateSize(), 50);
}

function confirmGuess() {
  if (!pendingGuess || showingResult) return;

  const round  = activeRounds[currentRound];
  const dist   = haversineKm(pendingGuess.lat, pendingGuess.lng, round.lat, round.lon);
  const { raw, final } = calcScore(dist, round.mult);

  totalScore += final;
  document.getElementById('total-score').textContent = totalScore;

  const result = { intersection: round, guess: pendingGuess, distKm: dist, rawScore: raw, finalScore: final, mult: round.mult };
  results.push(result);
  if (gameMode === 'daily') saveProgress();
  if (gameMode === 'practice') addPracticeCount(1);

  showRoundResult(result);
}

// ─── RESULT OVERLAY (sobre el mapa) ──────────────────────────────────────────

function showRoundResult(result) {
  const { intersection, guess, distKm, rawScore, finalScore, mult } = result;

  showingResult = true;

  // Mostrar marcador del target y línea en el mapa principal
  const guessLL  = L.latLng(guess.lat, guess.lng);
  const targetLL = L.latLng(intersection.lat, intersection.lon);
  L.marker(targetLL, { icon: makePinIcon('target') }).addTo(map);
  L.polyline([guessLL, targetLL], { color: 'rgba(255,255,255,0.5)', dashArray: '6,4', weight: 2 }).addTo(map);
  setTimeout(() => {
    map.invalidateSize();
    map.fitBounds(L.latLngBounds([guessLL, targetLL]).pad(0.35), { maxZoom: 14, animate: true });
  }, 50);

  // Rellenar overlay
  const scoreEl = document.getElementById('result-overlay-score');
  scoreEl.classList.remove('score-high', 'score-mid', 'score-low');
  scoreEl.classList.add(rawScore >= 75 ? 'score-high' : rawScore >= 40 ? 'score-mid' : 'score-low');

  document.getElementById('ro-pts').textContent      = finalScore;
  document.getElementById('ro-distance').textContent = `📏 ${formatDist(distKm)}`;
  document.getElementById('ro-street').textContent   = `📍 ${intersection.label}`;
  document.getElementById('ro-mult').textContent     =
    mult > 1 ? `Base ${rawScore} × ${mult} = ${finalScore} pts` : '';

  document.getElementById('result-bar').classList.remove('hidden');
}

function nextRound() {
  if (currentRound < totalRounds - 1) {
    startRound(currentRound + 1);
  } else {
    showFinal();
  }
}

// ─── FINAL ────────────────────────────────────────────────────────────────────

function showFinal() {
  document.getElementById('final-date-display').textContent  = todayDisplay();
  document.getElementById('final-score-number').textContent  = totalScore;
  document.getElementById('final-score-max').textContent     = `/${currentMaxScore()}`;

  const list = document.getElementById('final-rounds-list');
  list.innerHTML = '';

  results.forEach((r, i) => {
    const zClass = i < 2 ? 'z1' : i === 2 ? 'z2' : 'z3';
    const row    = document.createElement('div');
    row.className = 'final-round-row';
    row.innerHTML = `
      <span class="frow-num ${zClass}">${i + 1}</span>
      <div class="frow-info">
        <div class="frow-street">${r.intersection.street_label}</div>
        <div class="frow-location">${r.intersection.location_label}</div>
      </div>
      <div class="frow-score">
        <div class="frow-pts">${r.finalScore} pts</div>
        <div class="frow-dist">${formatDist(r.distKm)}</div>
      </div>
    `;
    list.appendChild(row);
  });

  const shareBtn = document.getElementById('btn-share');
  const backBtn  = document.getElementById('btn-back-menu');
  const note     = document.getElementById('final-note');

  if (gameMode === 'practice') {
    shareBtn.classList.add('hidden');
    backBtn.classList.remove('hidden');
    const remaining = Math.max(0, PRACTICE_MAX - getPracticeCount());
    note.textContent = remaining > 0
      ? `Te quedan ${remaining} cruces de práctica hoy.`
      : `Llegaste al límite de práctica de hoy. ¡Volvé mañana!`;
  } else {
    shareBtn.classList.remove('hidden');
    backBtn.classList.remove('hidden');
    note.textContent = 'Volvé mañana para cinco nuevos cruces.';
    saveProgress(true);
  }

  showScreen('screen-final');
}

// ─── SHARE ────────────────────────────────────────────────────────────────────

function scoreEmoji(raw) {
  if (raw >= 98) return '🔥';
  if (raw >= 90) return '🏅';
  if (raw >= 75) return '👏';
  if (raw >= 55) return '🎉';
  if (raw >= 35) return '🌞';
  if (raw >= 15) return '😬';
  return '💀';
}

const MONTH_NAMES = ['enero','febrero','marzo','abril','mayo','junio','julio','agosto','septiembre','octubre','noviembre','diciembre'];

function todayLongDisplay() {
  const d = new Date();
  return `${String(d.getDate()).padStart(2,'0')} de ${MONTH_NAMES[d.getMonth()]}, ${d.getFullYear()}`;
}

function buildShareText() {
  const scores = results
    .map(r => `${r.rawScore} ${scoreEmoji(r.rawScore)} (${formatDist(r.distKm)})`)
    .join(' | ');
  return [
    `📍 ¿Dónde estoy? AMBA${gameMode !== 'amba' && gameMode !== 'practice' ? ` — ${MODE_LABELS[gameMode]}` : ''}`,
    `🗓️ ${todayLongDisplay()}: *${totalScore}/${currentMaxScore()}*`,
    scores,
  ].join('\n');
}

function share() {
  const text = buildShareText();
  const url  = window.location.href.split('?')[0];
  const full = `${text}\n${url}`;

  const showCopied = () => {
    const el = document.getElementById('share-copied');
    el.classList.remove('hidden');
    setTimeout(() => el.classList.add('hidden'), 2500);
  };

  if (navigator.clipboard && navigator.clipboard.writeText) {
    navigator.clipboard.writeText(full).then(showCopied).catch(() => fallbackCopy(full, showCopied));
  } else {
    fallbackCopy(full, showCopied);
  }
}

function fallbackCopy(text, cb) {
  const ta = document.createElement('textarea');
  ta.value = text;
  Object.assign(ta.style, { position: 'fixed', opacity: '0', top: '0', left: '0' });
  document.body.appendChild(ta);
  ta.focus(); ta.select();
  try { document.execCommand('copy'); cb(); } catch(e) {}
  document.body.removeChild(ta);
}

// ─── PERSISTENCE ─────────────────────────────────────────────────────────────

function saveProgress(done = false) {
  try {
    localStorage.setItem(`amba-game-${gameMode}-${today()}`, JSON.stringify({
      results, totalScore, currentRound, done
    }));
  } catch(e) {}
}

function loadDailyProgress(modeKey) {
  try {
    const raw = localStorage.getItem(`amba-game-${modeKey}-${today()}`);
    return raw ? JSON.parse(raw) : null;
  } catch { return null; }
}

// ─── DAILY MODES ─────────────────────────────────────────────────────────────

function pickZoneDaily(modeKey, zoneNames) {
  const seed  = dateSeed(`${today()}-${modeKey}`);
  const rand  = seededRng(seed);
  const pool  = [].concat(...zoneNames.map(z => INTERSECTIONS_DB.zones[z]));
  const usedIds = new Set();
  const picks = [];
  let attempts = 0;
  while (picks.length < 5 && attempts < pool.length * 10) {
    attempts++;
    const idx  = Math.floor(rand() * pool.length);
    const cand = pool[idx];
    if (usedIds.has(cand.id)) continue;
    usedIds.add(cand.id);
    picks.push({ ...cand, mult: 1 });
  }
  return picks;
}

const DAILY_MODES = {
  amba: { maxScore: 1000, pick: () => pickDaily(INTERSECTIONS_DB) },
  caba: { maxScore: 500,  pick: () => pickZoneDaily('caba', ['caba']) },
  gba:  { maxScore: 500,  pick: () => pickZoneDaily('gba',  ['cordon1', 'cordon2', 'cordon3']) },
};

const MODE_LABELS = { amba: 'AMBA', caba: 'CABA', gba: 'GBA', practice: 'Práctica' };

function currentMaxScore() {
  if (gameMode === 'practice') return totalRounds * 100;
  return DAILY_MODES[gameMode] ? DAILY_MODES[gameMode].maxScore : totalRounds * 100;
}

// ─── BOOT ─────────────────────────────────────────────────────────────────────

function resetGameState() {
  currentRound = 0;
  totalScore   = 0;
  results      = [];
  document.getElementById('total-score').textContent = '0';
}

function startDailyMode(modeKey) {
  const cfg = DAILY_MODES[modeKey];
  gameMode    = modeKey;
  totalRounds = 5;
  document.getElementById('score-max').textContent = `/${cfg.maxScore}`;

  const saved = loadDailyProgress(modeKey);
  if (saved && saved.done) {
    results      = saved.results;
    totalScore   = saved.totalScore;
    currentRound = 5;
    document.getElementById('total-score').textContent = totalScore;
    showFinal();
    return;
  }

  resetGameState();
  activeRounds = cfg.pick();
  showScreen('screen-game');
  initMap();
  startRound(0);
}

function startPractice() {
  const remaining = PRACTICE_MAX - getPracticeCount();
  if (remaining <= 0) return;

  gameMode    = 'practice';
  totalRounds = Math.min(PRACTICE_ROUND_SIZE, remaining);
  document.getElementById('score-max').textContent = `/${totalRounds * 100}`;
  resetGameState();
  activeRounds = pickPractice(totalRounds);
  showScreen('screen-game');
  initMap();
  startRound(0);
}

function updatePracticeButton() {
  const remaining = Math.max(0, PRACTICE_MAX - getPracticeCount());
  const btn = document.getElementById('btn-practice');
  const note = document.getElementById('practice-date');
  if (remaining <= 0) {
    btn.disabled = true;
    note.textContent = 'Práctica: completaste el límite de hoy (volvé mañana)';
  } else {
    btn.disabled = false;
    note.textContent = `Práctica: cruces aleatorios de todo el AMBA (te quedan ${remaining} hoy)`;
  }
}

function boot() {
  document.getElementById('intro-date').textContent = `Cruces del ${todayDisplay()}`;
  updatePracticeButton();

  document.getElementById('btn-start').addEventListener('click', () => startDailyMode('amba'));
  document.getElementById('btn-start-caba').addEventListener('click', () => startDailyMode('caba'));
  document.getElementById('btn-start-gba').addEventListener('click', () => startDailyMode('gba'));
  document.getElementById('btn-practice').addEventListener('click', startPractice);

  document.getElementById('btn-confirm').addEventListener('click', () => {
    hideConfirmOverlay();
    confirmGuess();
  });
  document.getElementById('btn-cancel-guess').addEventListener('click', () => {
    hideConfirmOverlay();
    if (guessMarker) { map.removeLayer(guessMarker); guessMarker = null; }
    pendingGuess = null;
  });

  document.getElementById('btn-next-round').addEventListener('click', nextRound);
  document.getElementById('btn-share').addEventListener('click', share);
  document.getElementById('btn-back-menu').addEventListener('click', () => {
    updatePracticeButton();
    showScreen('screen-intro');
  });
}

document.addEventListener('DOMContentLoaded', boot);
